// #66 — sprite data → the text of an ES module.
//
// Kept apart from the build stage for one reason: this is the only place that
// decides FORMATTING, and formatting is where determinism is usually lost.
// Criterion 3 is "running the generator twice on the same input produces
// byte-identical output", so there is deliberately no timestamp, no source path,
// no hostname and no "generated by ralph 0.19.1" version stamp in the banner —
// each of those would make a rerun a diff even when the sprite did not change.
//
// The emitted module's shape is the contract lib/sprite-render.js consumes:
// `palette` as RGB triples and `frames` as `{ delayMs, rows }`, one row string
// per pixel row, one base36 character (or '.') per pixel.
//
// PURE: text in, text out. No fs — scripts/generate-sprite.js writes the file.

// What a row may contain. Enforced rather than assumed, because these strings go
// straight inside single quotes in generated source: a stray quote or backslash
// would emit a module that does not parse, and the failure would surface as a
// syntax error in whatever imports it.
const ROW_PATTERN = /^[0-9a-z.]*$/

function assertChannel(value, entryIndex, channelIndex) {
  if (!Number.isInteger(value) || value < 0 || value > 255) {
    throw new RangeError(
      `emit-sprite-module: palette entry ${entryIndex} channel ${channelIndex} must be an ` +
        `integer in 0..255 (got ${value})`,
    )
  }
}

function paletteLines(palette) {
  if (!Array.isArray(palette) || palette.length === 0) {
    throw new TypeError('emit-sprite-module: palette must be a non-empty array of [r, g, b] triples')
  }
  return palette.map((entry, index) => {
    if (!Array.isArray(entry) || entry.length !== 3) {
      throw new TypeError(`emit-sprite-module: palette entry ${index} must be an [r, g, b] triple`)
    }
    entry.forEach((channel, channelIndex) => assertChannel(channel, index, channelIndex))
    return `  [${entry[0]}, ${entry[1]}, ${entry[2]}],`
  })
}

function frameLines(frames, width, height) {
  if (!Array.isArray(frames) || frames.length === 0) {
    throw new TypeError('emit-sprite-module: frames must be a non-empty array')
  }
  const lines = []
  frames.forEach((frame, index) => {
    if (!Number.isFinite(frame.delayMs) || frame.delayMs < 0) {
      throw new RangeError(
        `emit-sprite-module: frame ${index} delayMs must be a non-negative number (got ${frame.delayMs})`,
      )
    }
    if (!Array.isArray(frame.rows) || frame.rows.length !== height) {
      throw new RangeError(
        `emit-sprite-module: frame ${index} must hold ${height} row(s), got ` +
          `${Array.isArray(frame.rows) ? frame.rows.length : typeof frame.rows}`,
      )
    }
    lines.push('  {', `    delayMs: ${frame.delayMs},`, '    rows: [')
    frame.rows.forEach((row, y) => {
      if (typeof row !== 'string' || row.length !== width) {
        throw new RangeError(
          `emit-sprite-module: frame ${index} row ${y} must be a ${width}-character string`,
        )
      }
      if (!ROW_PATTERN.test(row)) {
        throw new RangeError(
          `emit-sprite-module: frame ${index} row ${y} holds a character outside 0-9a-z and '.'`,
        )
      }
      lines.push(`      '${row}',`)
    })
    lines.push('    ],', '  },')
  })
  return lines
}

/**
 * Renders sprite data as the source of an ES module.
 *
 * @param {object} sprite output of buildSprite()
 * @returns {string} module source, one trailing newline, deterministic
 */
export function emitSpriteModule(sprite) {
  if (sprite === null || typeof sprite !== 'object') {
    throw new TypeError('emit-sprite-module: expected a sprite object from buildSprite()')
  }
  const { width, height, palette, frames, box, source } = sprite

  const geometry =
    box && source
      ? `// Cropped from a ${source.width}x${source.height} source at (${box.left}, ${box.top}), ` +
        `${box.width}x${box.height} pixels.`
      : '// Cropped from the source GIF bounding box.'

  const lines = [
    '// GENERATED FILE — do not edit by hand.',
    '//',
    '// Written by `node scripts/generate-sprite.js <source.gif>` (#66). The generator',
    '// is deterministic: the same GIF and the same flags reproduce this file byte for',
    '// byte, so regenerate it instead of patching it.',
    '//',
    `// ${width}x${height} cells, ${frames.length} frame(s), one palette shared by all of them.`,
    geometry,
    '// Rows hold one character per pixel: a base36 palette index, or "." for a',
    '// transparent pixel. lib/sprite-render.js turns that into terminal rows.',
    '',
    `export const spriteWidth = ${width}`,
    `export const spriteHeight = ${height}`,
    '',
    'export const palette = [',
    ...paletteLines(palette),
    ']',
    '',
    'export const frames = [',
    ...frameLines(frames, width, height),
    ']',
  ]
  return `${lines.join('\n')}\n`
}
